// Evaluate Meta's GET webhook verification handshake.
// The verify token itself is never read here -- only a one-way HMAC
// "commitment" (EXPECTED_COMMITMENT, computed once at setup time, NOT a
// secret) is compared against an HMAC computed over the incoming
// hub.verify_token using the real secret via the bound "crypto" credential
// (see the "Hash GET Verify Token" node). If the incoming token matches the
// real secret, the two HMACs are guaranteed equal; if not, they differ.

function timingSafeEqualHex(a, b) {
  if (typeof a !== 'string' || typeof b !== 'string') return false;
  if (a.length !== b.length) return false;
  let diff = 0;
  for (let i = 0; i < a.length; i++) {
    diff |= a.charCodeAt(i) ^ b.charCodeAt(i);
  }
  return diff === 0;
}

// Set once at deployment time: HMAC-SHA256(key=YOUR_VERIFY_TOKEN,
// message=YOUR_VERIFY_TOKEN), computed OUTSIDE n8n. This is a public,
// non-reversible commitment -- NOT the verify token itself, safe to store
// as a plain value.
const EXPECTED_COMMITMENT = 'de6df3954b12e7fb2bd26cd44d535511966708d535383d10aaa7e83207408480';

const trigger = $('GET Trigger').first().json;
const mode = trigger.query && trigger.query['hub.mode'];
const challenge = trigger.query && trigger.query['hub.challenge'];
const computedHash = $input.first().json.incomingHash;

const modeOk = mode === 'subscribe';
const tokenOk = timingSafeEqualHex(computedHash, EXPECTED_COMMITMENT);
const verified = modeOk && tokenOk;

return [{ json: { verified: verified ? 'yes' : 'no', challenge: verified && typeof challenge === 'string' ? challenge : '' } }];

// Validate Meta's X-Hub-Signature-256 header against an HMAC-SHA256 of the
// EXACT raw request body (never a re-parsed/re-serialized copy -- the
// Webhook trigger's "Raw Body" option preserves the original bytes exactly,
// and the "Compute POST Body HMAC" node hashes that binary data directly).

function timingSafeEqualHex(a, b) {
  if (typeof a !== 'string' || typeof b !== 'string') return false;
  if (a.length !== b.length) return false;
  let diff = 0;
  for (let i = 0; i < a.length; i++) {
    diff |= a.charCodeAt(i) ^ b.charCodeAt(i);
  }
  return diff === 0;
}

const trigger = $('POST Trigger').first().json;
const headers = trigger.headers || {};
const signatureHeader = headers['x-hub-signature-256'];
const computedHex = $input.first().json.bodyHmac;

let verified = false;
if (typeof signatureHeader === 'string' && signatureHeader.startsWith('sha256=')) {
  const providedHex = signatureHeader.slice('sha256='.length).toLowerCase();
  verified = timingSafeEqualHex(providedHex, computedHex);
}

return [{ json: { verified: verified ? 'yes' : 'no' } }];
